# Origin side: tag responses by the data they render, purge by tag when that data changes.
# The CDN client is abstract; Fastly (Surrogate-Key) and Cloudflare (Cache-Tag) both offer purge-by-tag APIs.
from dataclasses import dataclass
from typing import Protocol


class CdnClient(Protocol):
    def purge_tags(self, tags: list[str], soft: bool = True) -> None: ...


@dataclass
class Product:
    id: int
    category: str
    price_cents: int


def product_page_headers(p: Product) -> dict[str, str]:
    return {
        # Browsers: short. CDN: long, because we purge on change. Serve stale while refetching.
        "Cache-Control": "public, max-age=60, s-maxage=86400, stale-while-revalidate=300, stale-if-error=86400",
        "Surrogate-Key": f"product-{p.id} category-{p.category}",
    }


class CatalogService:
    def __init__(self, repo, cdn: CdnClient, outbox):
        self.repo, self.cdn, self.outbox = repo, cdn, outbox

    def update_price(self, product_id: int, price_cents: int) -> None:
        with self.repo.transaction() as tx:
            p = tx.get_product(product_id)
            p.price_cents = price_cents
            tx.save(p)
            # Record the purge in the same transaction so a crash cannot lose it.
            self.outbox.add(tx, "cdn.purge", {"tags": [f"product-{p.id}", f"category-{p.category}"]})

    def on_outbox_event(self, payload: dict) -> None:
        # Soft purge marks stale instead of deleting: users keep getting fast (slightly old) hits
        # while the edge refetches, which avoids a thundering herd on the origin.
        self.cdn.purge_tags(payload["tags"], soft=True)

// Cloudflare Workers style edge handler: normalise the cache key, bypass for sessions, serve stale on error.
const TRACKING = new Set(["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "gclid", "fbclid"]);

function deviceBucket(ua: string | null): "mobile" | "desktop" {
  return ua && /Mobi|Android|iPhone/i.test(ua) ? "mobile" : "desktop";
}

function cacheKey(req: Request): Request {
  const url = new URL(req.url);
  url.hostname = url.hostname.toLowerCase();
  const kept = [...url.searchParams.entries()]
    .filter(([k]) => !TRACKING.has(k.toLowerCase()))
    .sort(([a], [b]) => a.localeCompare(b));
  url.search = new URLSearchParams(kept).toString();
  // Put the small, bounded variant into the key instead of Vary: User-Agent.
  url.searchParams.set("__d", deviceBucket(req.headers.get("user-agent")));
  return new Request(url.toString(), { method: "GET" });
}

export default {
  async fetch(req: Request, _env: unknown, ctx: ExecutionContext): Promise<Response> {
    if (req.method !== "GET" || req.headers.get("cookie")?.includes("session=")) {
      return fetch(req); // personalised or write: never shared-cached
    }
    const cache = caches.default;
    const key = cacheKey(req);

    // Long-lived copy used only when origin fails: the Cache API itself never returns expired entries.
    const fallbackKey = new Request(`${key.url}&__fallback=1`);

    const hit = await cache.match(key);
    if (hit) return hit;

    try {
      const origin = await fetch(req, { signal: AbortSignal.timeout(3000) });
      if (origin.status >= 500) throw new Error(`origin ${origin.status}`);
      if (origin.ok && !origin.headers.has("set-cookie")) {
        const backup = new Response(origin.clone().body, origin);
        backup.headers.set("cache-control", "public, max-age=86400");
        // Store without delaying the user.
        ctx.waitUntil(Promise.all([cache.put(key, origin.clone()), cache.put(fallbackKey, backup)]));
      }
      return origin;
    } catch {
      const stale = await cache.match(fallbackKey);
      return stale ?? new Response("Service unavailable", { status: 503, headers: { "retry-after": "30" } });
    }
  },
};

package telemetry

import (
	"net/http"
	"strconv"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promauto"
)

var (
	requests = promauto.NewCounterVec(prometheus.CounterOpts{
		Name: "http_requests_total",
		Help: "HTTP requests by route template, method and status code.",
	}, []string{"route", "method", "code"})

	latency = promauto.NewHistogramVec(prometheus.HistogramOpts{
		Name: "http_request_duration_seconds",
		Help: "Request latency. A bucket boundary sits exactly on the 300 ms SLO threshold.",
		Buckets: []float64{0.025, 0.05, 0.1, 0.2, 0.3, 0.5, 1, 2, 5},
	}, []string{"route", "method"})
)

type statusRecorder struct {
	http.ResponseWriter
	code int
}

func (r *statusRecorder) WriteHeader(code int) {
	r.code = code
	r.ResponseWriter.WriteHeader(code)
}

// Instrument wraps a handler. route must be the template ("/users/{id}"), never the raw path,
// otherwise every user id becomes a new time series.
func Instrument(route string, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		start := time.Now()
		rec := &statusRecorder{ResponseWriter: w, code: http.StatusOK}
		next.ServeHTTP(rec, req)
		requests.WithLabelValues(route, req.Method, strconv.Itoa(rec.code)).Inc()
		latency.WithLabelValues(route, req.Method).Observe(time.Since(start).Seconds())
	})
}

// Multiwindow, multi-burn-rate evaluation (SRE Workbook, "Alerting on SLOs"). Pure, so it is easy to test.
type WindowCounts = { good: number; total: number };
type Severity = "page" | "ticket";

interface BurnRule {
  severity: Severity;
  burnRate: number;
  long: string; // window names must exist in the counts map
  short: string;
}

const RULES: BurnRule[] = [
  { severity: "page", burnRate: 14.4, long: "1h", short: "5m" },
  { severity: "page", burnRate: 6, long: "6h", short: "30m" },
  { severity: "ticket", burnRate: 1, long: "3d", short: "6h" },
];

const errorRatio = ({ good, total }: WindowCounts): number => (total === 0 ? 0 : (total - good) / total);

export interface Alert {
  severity: Severity;
  rule: string;
  burnRate: number;
  budgetConsumedPct: number; // share of the whole SLO window's budget used during the long window
}

export function evaluate(
  slo: number, // e.g. 0.999
  sloWindowHours: number, // e.g. 720 for 30 days
  counts: Record<string, WindowCounts>,
  windowHours: Record<string, number>,
  minRequests = 100,
): Alert | null {
  const budget = 1 - slo;
  for (const r of RULES) {
    const long = counts[r.long];
    const short = counts[r.short];
    if (!long || !short || long.total < minRequests) continue; // too little traffic to judge
    const longBurn = errorRatio(long) / budget;
    const shortBurn = errorRatio(short) / budget;
    if (longBurn >= r.burnRate && shortBurn >= r.burnRate) {
      return {
        severity: r.severity,
        rule: `${r.burnRate}x over ${r.long} and ${r.short}`,
        burnRate: Number(longBurn.toFixed(1)),
        budgetConsumedPct: Number(((longBurn * windowHours[r.long]) / sloWindowHours * 100).toFixed(1)),
      };
    }
  }
  return null;
}

// 1.5% errors over the last hour and 2% over the last 5 minutes against a 99.9% SLO pages:
// burn 15 >= 14.4 on both windows, about 2.1% of the 30-day budget gone.
