package resilience

import (
	"context"
	"errors"
	"math/rand/v2"
	"sync/atomic"
	"time"
)

// RetryBudget allows retries only while they stay under ratio of recent requests (e.g. 0.1 = 10%).
// Counters are reset by a ticker every window; kept minimal here.
type RetryBudget struct {
	requests, retries atomic.Int64
	ratio             float64
}

func (b *RetryBudget) OnRequest() { b.requests.Add(1) }

func (b *RetryBudget) TryRetry() bool {
	if float64(b.retries.Load()+1) > b.ratio*float64(b.requests.Load()) {
		return false
	}
	b.retries.Add(1)
	return true
}

var ErrNotRetryable = errors.New("not retryable")

// Do runs op up to maxAttempts times with full-jitter exponential backoff, never sleeping past the
// context deadline. op must be idempotent; it returns ErrNotRetryable (wrapped) for 4xx-style errors.
func Do(ctx context.Context, budget *RetryBudget, maxAttempts int, base, maxDelay time.Duration,
	op func(ctx context.Context) error) error {
	budget.OnRequest()
	var err error
	for attempt := 0; attempt < maxAttempts; attempt++ {
		if err = op(ctx); err == nil || errors.Is(err, ErrNotRetryable) {
			return err
		}
		if attempt == maxAttempts-1 || !budget.TryRetry() {
			break
		}
		backoff := min(maxDelay, base<<attempt)            // exponential cap
		sleep := time.Duration(rand.Int64N(int64(backoff))) // full jitter: uniform in [0, cap)
		if dl, ok := ctx.Deadline(); ok && time.Until(dl) < sleep {
			break // no time left for another attempt
		}
		select {
		case <-time.After(sleep):
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	return err
}

type State = "closed" | "open" | "half-open";

interface BreakerOptions {
  failureRateThreshold: number; // 0.5 = open when half the calls in the window fail
  minimumCalls: number; // do not judge on tiny samples
  windowSize: number; // number of recent outcomes kept
  openMs: number; // cool-down before probing
  halfOpenMaxCalls: number; // trial calls allowed while half-open
  isFailure?: (err: unknown) => boolean; // e.g. ignore 4xx
  now?: () => number; // injectable clock for tests
}

export class CircuitOpenError extends Error {}

export class CircuitBreaker {
  private state: State = "closed";
  private outcomes: boolean[] = []; // true = failure
  private openedAt = 0;
  private trials = 0;
  private trialSuccesses = 0;
  private readonly now: () => number;
  private readonly isFailure: (err: unknown) => boolean;

  constructor(private readonly opts: BreakerOptions) {
    this.now = opts.now ?? Date.now;
    this.isFailure = opts.isFailure ?? (() => true);
  }

  async call<T>(fn: () => Promise<T>, fallback?: () => T | Promise<T>): Promise<T> {
    if (this.state === "open") {
      if (this.now() - this.openedAt < this.opts.openMs) return this.reject(fallback);
      this.state = "half-open";
      this.trials = 0;
      this.trialSuccesses = 0;
    }
    if (this.state === "half-open") {
      if (this.trials >= this.opts.halfOpenMaxCalls) return this.reject(fallback);
      this.trials++;
    }

    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (err) {
      if (this.isFailure(err)) this.onFailure();
      else this.onSuccess(); // a 404 is a correct answer, not a sick dependency
      throw err;
    }
  }

  private onSuccess(): void {
    if (this.state === "half-open") {
      if (++this.trialSuccesses >= this.opts.halfOpenMaxCalls) this.close(); // all probes passed
      return;
    }
    this.record(false);
  }

  private onFailure(): void {
    if (this.state === "half-open") return this.open(); // one failed probe reopens
    this.record(true);
    const failures = this.outcomes.filter(Boolean).length;
    if (this.outcomes.length >= this.opts.minimumCalls && failures / this.outcomes.length >= this.opts.failureRateThreshold) {
      this.open();
    }
  }

  private record(failed: boolean): void {
    this.outcomes.push(failed);
    if (this.outcomes.length > this.opts.windowSize) this.outcomes.shift();
  }

  private open(): void {
    this.state = "open";
    this.openedAt = this.now();
    this.outcomes = [];
  }

  private close(): void {
    this.state = "closed";
    this.outcomes = [];
  }

  private async reject<T>(fallback?: () => T | Promise<T>): Promise<T> {
    if (fallback) return fallback();
    throw new CircuitOpenError("circuit open");
  }
}

